import {equipmentDisplayQuality,equipmentDisplayRarity} from './equipment-display.js';
import {equipmentIcon} from './equipment-art.js';
import {SLOTS,SLOTNAME,RARITY} from './engine.js';
import {icon} from './icons.js';
const esc=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderForgeInputPicker(s,{tab='materials',slot='all',page=0,selection=[],busy=false,materialGrid=()=>'',eligibleEquipment=[]}={}){
 const gearTab=tab==='equipment',selected=new Set(selection.filter(r=>r&&typeof r==='object'&&r.kind==='equipment').map(r=>r.id)),filtered=eligibleEquipment.filter(it=>slot==='all'||it.slot===slot),pages=Math.max(1,Math.ceil(filtered.length/12)),current=Math.max(0,Math.min(pages-1,Number.isInteger(page)?page:0));
 return `<section class="fusionInputPicker"><div class="fusionInputTabs"><button data-fusion-input-tab="materials" aria-pressed="${!gearTab}" ${busy?'disabled':''}>${icon('iron')}材料</button><button data-fusion-input-tab="equipment" aria-pressed="${gearTab}" ${busy?'disabled':''}>${icon('weapon')}装备</button><span>已投入 ${selection.length} / 5</span></div>${gearTab?`<div class="fusionFamilies"><button data-fusion-family="all" aria-pressed="${slot==='all'}" ${busy?'disabled':''}>全部</button>${SLOTS.map(k=>`<button data-fusion-family="${k}" aria-pressed="${slot===k}" title="${SLOTNAME[k]}" ${busy?'disabled':''}>${icon(k)}<small>${SLOTNAME[k]}</small></button>`).join('')}</div><div class="fusionGearGrid">${filtered.slice(current*12,current*12+12).map(it=>`<button class="fusionGearCard r${equipmentDisplayQuality(it)} ${it.set?'setFrame':''} ${selected.has(it.id)?'fusionSelected':''}" data-fusion-gear="${esc(it.id)}" aria-pressed="${selected.has(it.id)}" title="${esc(it.name)} · ${equipmentDisplayRarity(it)} · Lv.${it.level}" ${busy||selected.has(it.id)||selection.length>=5?'disabled':''}>${equipmentIcon(it,{size:32})}<small class="r${equipmentDisplayQuality(it)}text">Lv.${it.level}</small>${selected.has(it.id)?'<span class="fusionSelectedMark">已投入</span>':''}</button>`).join('')||'<p class="fusionEmpty">此类暂无可投入装备</p>'}</div>${pages>1?`<nav class="fusionPages"><button data-fusion-page="${current-1}" ${busy||current===0?'disabled':''}>←</button><span>${current+1} / ${pages}</span><button data-fusion-page="${current+1}" ${busy||current===pages-1?'disabled':''}>→</button></nav>`:''}<p class="fusionInputNote">已穿戴、锁定、方案引用与待改造装备不在投入列表。</p>`:materialGrid()}<p class="fusionInputNote">投入装备将被消耗；品质可能升降。优质材料 / 至臻装备更易获得神赐。</p></section>`;
}
